UPDATE t_console_resource SET parent_resource_id=#{parentResourceId},display_name=#{displayName},
    frontend_route=#{frontendRoute},component_key=#{componentKey},permission_id=#{permissionId},
    sort_order=#{sortOrder},status=#{status},version=version+1,update_time=#{updateTime}
WHERE resource_id=#{row.resourceId} AND channel='OPERATIONS' AND version=#{row.version}
